ALTER TABLE public.settings DROP CONSTRAINT settings_id_check;
CREATE SEQUENCE public.settings_row_id_seq START WITH 2;
ALTER TABLE public.settings ALTER COLUMN id SET DEFAULT nextval('public.settings_row_id_seq');
CREATE UNIQUE INDEX settings_one_row_per_store ON public.settings(store_id);
ALTER TABLE public.categories DROP CONSTRAINT categories_name_key;
ALTER TABLE public.categories ADD CONSTRAINT categories_store_name_key UNIQUE(store_id,name);
ALTER TABLE public.branches DROP CONSTRAINT branches_name_key;
ALTER TABLE public.branches ADD CONSTRAINT branches_store_name_key UNIQUE(store_id,name);
ALTER TABLE public.products DROP CONSTRAINT products_sku_key;
ALTER TABLE public.products ADD CONSTRAINT products_store_sku_key UNIQUE(store_id,sku);
ALTER TABLE public.products DROP CONSTRAINT products_barcode_key;
ALTER TABLE public.products ADD CONSTRAINT products_store_barcode_key UNIQUE(store_id,barcode);
ALTER TABLE public.payment_types DROP CONSTRAINT payment_types_code_key;
ALTER TABLE public.payment_types ADD CONSTRAINT payment_types_store_code_key UNIQUE(store_id,code);
ALTER TABLE public.journal_lines DROP CONSTRAINT journal_lines_account_code_fkey;
ALTER TABLE public.gl_accounts DROP CONSTRAINT gl_accounts_pkey;
ALTER TABLE public.gl_accounts ADD CONSTRAINT gl_accounts_pkey PRIMARY KEY(store_id,code);
ALTER TABLE public.journal_lines ADD CONSTRAINT journal_lines_store_account_fkey FOREIGN KEY(store_id,account_code) REFERENCES public.gl_accounts(store_id,code);
CREATE OR REPLACE FUNCTION public.save_gl_account(p_code text,p_name text,p_type text,p_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_view_accounts(auth.uid()) THEN RAISE EXCEPTION 'Not authorised'; END IF; IF coalesce(trim(p_code),'')='' OR coalesce(trim(p_name),'')='' THEN RAISE EXCEPTION 'Account code and name are required'; END IF; INSERT INTO public.gl_accounts(store_id,code,name,type,active) VALUES(public.current_store_id(),trim(p_code),trim(p_name),p_type,coalesce(p_active,true)) ON CONFLICT(store_id,code) DO UPDATE SET name=excluded.name,active=excluded.active,type=CASE WHEN gl_accounts.system THEN gl_accounts.type ELSE excluded.type END; END $$;
CREATE OR REPLACE FUNCTION public.set_payment_type_code() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE base text; candidate text; n int:=0; BEGIN IF coalesce(trim(NEW.code),'')='' THEN base:=lower(trim(regexp_replace(coalesce(NEW.name,''),'[^a-zA-Z0-9]+','_','g'),'_')); IF base='' THEN base:='method'; END IF; candidate:=base; WHILE EXISTS(SELECT 1 FROM public.payment_types WHERE code=candidate AND store_id=NEW.store_id AND id<>NEW.id) LOOP n:=n+1; candidate:=base||'_'||n; END LOOP; NEW.code:=candidate; END IF; RETURN NEW; END $$;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.check_store_references()'::regprocedure) INTO d; d:=replace(d,'WHERE %I::text=$1','WHERE %I::text=$1 AND store_id=$2'); d:=replace(d,'USING ref_value;','USING ref_value,NEW.store_id;'); EXECUTE d; END $$;